/**
 * Workbench configuration.
 *
 * @public
 */
export declare interface Config {
  /**
   * The organization ID to use when rendering the workbench. Required — the
   * Sanity CLI rejects an `unstable_defineApp` call without it, so a host can
   * never reach the workbench without one.
   */
  organizationId: string;
}

/**
 * Connect a client to the shared core: this copy's identity plus its topic
 * versions, recast per topic against the install in either direction (see
 * {@link topicAdapters}).
 *
 * The one connect-time failure is a core-protocol mismatch, which yields an
 * inert client rather than a throw here — `connect` runs at module evaluation,
 * where a throw would take the whole module graph down with it.
 * @public
 */
export declare function connect(core: Bus, config?: ConnectOptions): Bus;

/**
 * Options for {@link connect}. `appId` is stamped on every message the client
 * emits and scopes its lifetime (see {@link disconnectApp}); `migrations` pins
 * the client's per-topic versions and defaults to this copy's bundled chains.
 * @public
 */
export declare interface ConnectOptions {
  appId?: string;
  migrations?: ReadonlyMap<string, readonly TopicMigration[]>;
}

