/**
 * Declare state topics. A value seeds the topic; `undefined` leaves it
 * suspending (reads wait for the first emit).
 * @public
 */
export declare function defineStateTopics(
  target: Bus,
  topics: Partial<{
    [K in StateTopic]: ValueOf<K> | undefined;
  }>,
): void;

/**
 * Tear down everything an app holds on the bus in one abort. The next `connect`
 * for the same app id starts a fresh lifetime, so a reload replaces a
 * generation of handlers instead of stacking a new one.
 * @public
 */
export declare function disconnectApp(bus: Bus, appId: string): void;

/**
 * `emit` options. `timeout` (default 5s; `null` disables the deadline so the
 * `signal` governs) composes with the `signal` — whichever fires first rejects.
 * @public
 */
declare interface EmitOptions extends AbortOptions {
  timeout?: number | null;
}

/**
 * An event `emit`'s result. Awaiting it arms the failure machinery; not awaiting
 * is pure fire-and-forget.
 * @public
 */
declare interface EmitResult<R> extends PromiseLike<R> {
  catch<T = never>(
    onRejected?: (reason: unknown) => T | PromiseLike<T>,
  ): Promise<R | T>;
  finally(onFinally?: () => void): Promise<R>;
}

/**
 * Names of all declared event topics.
 * @public
 */
declare type EventTopic = {
  [K in TopicName]: Topics[K] extends {
    kind: "event";
  }
    ? K
    : never;
}[TopicName];

/**
 * Declares an event topic: a stream of occurrences with no memory. Declaring a
 * `reply` makes it a request topic — an awaited `emit` resolves with that reply.
 * @public
 */
declare type EventTopicDef<P, R = never> = {
  kind: "event";
  payload: P;
  reply?: R;
};

