/**
 * One envelope flowing through a topic.
 * @public
 */
declare interface Message<T> {
  type: TopicName;
  payload: T;
  meta: OsMeta;
}

/**
 * What an event-topic handler receives: the envelope plus `reply` (routed back
 * to the awaiting caller) and `signal` (aborts when that caller stops waiting —
 * never on a fire-and-forget emit).
 * @public
 */
declare interface OsMessage<T, R = never> extends Message<T> {
  reply(value: R): void;
  readonly signal: AbortSignal;
}

/**
 * Message metadata. Reply routing is carried by the delivery mechanism, not the
 * envelope, so this is provenance only.
 * @public
 */
declare interface OsMeta {
  appId: string;
  timestamp: number;
}

/**
 * A panel's view-component slots, in render order — each its own federation
 * island (`${id}/views/${name}/${component}`). The authoring counterpart that
 * drives the build's per-slot codegen lives with the CLI define helpers.
 * @public
 */
declare type PanelComponent = "title" | "panel";

/**
 * The payload type of an event topic.
 * @public
 */
declare type PayloadOf<K extends EventTopic> =
  Topics[K] extends EventTopicDef<infer P, infer _R> ? P : never;

